// src/lib/mcp/tools/list-vehicles.ts
var list_vehicles_default = defineTool({
  name: "list_vehicles",
  title: "List vehicles",
  description: "List the electric vehicles available for subscription, with monthly price, range and body type.",
  inputSchema: {
    type: z.enum(["sedan", "suv", "truck", "sports"]).optional().describe("Only return vehicles of this body type."),
    maxMonthlyPrice: z.number().positive().optional().describe("Only return vehicles at or below this monthly price in USD.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ type, maxMonthlyPrice }) => {
    const items = vehicles.filter((v) => type ? v.type === type : true).filter((v) => maxMonthlyPrice ? v.price <= maxMonthlyPrice : true).map((v) => ({
      id: v.id,
      model: v.model,
      type: v.type,
      monthlyPrice: v.price,
      tagline: v.tagline,
      rangeMiles: v.performance.range,
      available: v.available
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { vehicles: items }
    };
  }
});

// src/lib/mcp/tools/get-vehicle.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@2.2.0";
import { z as z2 } from "npm:zod@^3.25.76";
var get_vehicle_default = defineTool2({
  name: "get_vehicle",
  title: "Get vehicle details",
  description: "Get full details for one vehicle: pricing, performance, features, available colors and image paths.",
  inputSchema: {
    id: z2.string().trim().min(1).describe("Vehicle id, for example model-3, model-y or cybertruck.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const vehicle = vehicles.find((v) => v.id === id.toLowerCase());
    if (!vehicle) {
      throw new ToolError(
        `No vehicle with id "${id}". Known ids: ${vehicles.map((v) => v.id).join(", ")}.`
      );
    }
    const details = {
      id: vehicle.id,
      model: vehicle.model,
      type: vehicle.type,
      monthlyPrice: vehicle.price,
      priceUnit: vehicle.priceUnit,
      tagline: vehicle.tagline,
      features: vehicle.features,
      performance: vehicle.performance,
      available: vehicle.available,
      colors: vehicle.colors,
      images: vehicle.colorImages ?? { default: vehicle.image },
      detailsPath: `/vehicles/${vehicle.id}`
    };
    return {
      content: [{ type: "text", text: JSON.stringify(details, null, 2) }],
      structuredContent: { vehicle: details }
    };
  }
});

